const items = $input.all();
const groups = new Map();

for (const item of items) {
  const payload = item && item.json ? item.json : {};
  const list = Array.isArray(payload.batches)
    ? payload.batches
    : (Array.isArray(payload.open_batches)
      ? payload.open_batches
      : (Array.isArray(payload.items) ? payload.items : []));

  for (const row of list) {
    if (!row || !row.provider_batch_id) continue;
    const bid = String(row.provider_batch_id).trim();
    if (!bid) continue;
    if (!groups.has(bid)) {
      groups.set(bid, {
        provider_batch_id: bid,
        api_base_url: String(row.api_base_url || payload.api_base_url || 'https://chatlytics.de').trim().replace(/\/+$/, '') || 'https://chatlytics.de',
        pending_items: []
      });
    }
    groups.get(bid).pending_items.push(row);
  }
}

return Array.from(groups.values()).map(g => ({ json: g }));

const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const resp = items[i].json || {};
  let meta = {};
  try {
    if (typeof $ === 'function') {
      meta = $('Deduplicate OpenRouter Batches').itemMatching(i)?.json || $('Deduplicate OpenRouter Batches').all()[i]?.json || {};
    }
  } catch (_) {}

  const batchId = meta.provider_batch_id || resp.id || null;
  const apiBaseUrl = meta.api_base_url || 'https://chatlytics.de';
  const pending = Array.isArray(meta.pending_items) ? meta.pending_items : [];
  const statusLower = String(resp.status || '').toLowerCase();

  if (resp.error || (typeof resp.statusCode === 'number' && resp.statusCode >= 400) || ['failed', 'expired', 'cancelled', 'canceled'].includes(statusLower)) {
    const errMsg = (resp.error && (resp.error.message || JSON.stringify(resp.error)))
      || resp.message
      || ('OpenRouter Batch status: ' + (resp.status || 'failed'));
    out.push({
      json: {
        _batch_route: 'failed',
        api_base_url: apiBaseUrl,
        provider_batch_id: batchId,
        custom_ids: pending.map(p => p.custom_id).filter(Boolean),
        error_message: String(errMsg)
      }
    });
    continue;
  }

  if (statusLower !== 'completed' && !Array.isArray(resp.results)) {
    continue;
  }

  const resultsArr = Array.isArray(resp.results) ? resp.results : [];
  const byCustomId = new Map();
  for (const r of resultsArr) {
    if (r && r.custom_id) {
      byCustomId.set(String(r.custom_id), r);
    }
  }

  for (const p of pending) {
    const matched = byCustomId.get(String(p.custom_id || ''));
    if (!matched) continue;

    const statusCode = matched.status_code ?? matched.response?.status_code ?? 200;
    const body = matched.response?.body || matched.body || matched;
    const itemError = matched.error || body?.error || (statusCode >= 400 ? { message: 'OpenRouter batch item HTTP ' + statusCode } : null);

    out.push({
      json: {
        ...p,
        ...body,
        _batch_route: 'completed',
        raw_payload_source: 'openrouter_batch',
        api_base_url: p.api_base_url || apiBaseUrl,
        batch_id: batchId,
        provider_batch_id: batchId,
        execution_strategy: 'batch_api',
        prompt_cache_key: null,
        eu_hosted: false,
        error: itemError || undefined
      }
    });
  }
}

return out;

const items = $input.all();
const DEFAULT_ALLOWED_PREFIXES = [
  'openai', 'google', 'anthropic', 'mistralai', 'x-ai',
  'deepseek', 'qwen', 'xiaomi', 'z-ai', 'zhipu',
  'meta-llama', 'meta', 'nvidia', 'azure', 'microsoft', 'perplexity',
  'moonshotai', 'moonshot', 'minimax'
];

const blockedFragments = [
  'embedding', 'embed', 'tts', 'whisper', 'dall-e', 'sora', 'imagen',
  'veo', 'lyria', 'music', 'moderation', 'guard', 'realtime',
  '-image', 'image-preview', 'flux', 'midjourney', 'audio', 'speech'
];

const firstItem = items[0] && items[0].json ? items[0].json : {};
let reqBody = (firstItem.body && typeof firstItem.body === 'object') ? firstItem.body : {};
if (typeof $ === 'function') {
  try {
    const routeNode = $('Route Discover Models');
    const rJson = routeNode && routeNode.first && routeNode.first().json ? routeNode.first().json : null;
    if (rJson && rJson.body && typeof rJson.body === 'object') {
      reqBody = rJson.body;
    } else if (rJson && typeof rJson === 'object') {
      reqBody = rJson;
    }
  } catch (_) {}
}
const dynamicAllowed = Array.isArray(reqBody.allowed_providers)
  ? reqBody.allowed_providers.map(p => String(p || '').trim().toLowerCase()).filter(Boolean)
  : DEFAULT_ALLOWED_PREFIXES.slice();
if (dynamicAllowed.includes('z-ai') && !dynamicAllowed.includes('zhipu')) dynamicAllowed.push('zhipu');
if (dynamicAllowed.includes('moonshotai') && !dynamicAllowed.includes('moonshot')) dynamicAllowed.push('moonshot');
const allowedPrefixes = new Set(dynamicAllowed);

if (firstItem.error || (typeof firstItem.statusCode === 'number' && firstItem.statusCode >= 400) || !Array.isArray(firstItem.data)) {
  const errMsg = (firstItem.error && (firstItem.error.message || JSON.stringify(firstItem.error)))
    || firstItem.message
    || 'OpenRouter Model API unreachable';
  return [{
    json: {
      status: 'error',
      action: 'discover_models',
      source: 'openrouter_live_api',
      message: String(errMsg),
      timestamp: new Date().toISOString(),
      provider_credentials: [
        {
          provider: 'openrouter',
          credential_id: 'tjmYBMIQa9Fo3kYL',
          credential_name: 'OpenRouter - Chatlytics - Chatlytics-dev-1',
          status: 'error'
        }
      ],
      providers: [],
      models: []
    }
  }];
}

const rawModels = firstItem.data;
const batchBases = new Set();
const providersMap = new Map();

for (const m of rawModels) {
  if (!m || typeof m.id !== 'string') continue;
  const id = m.id.trim();
  if (id.endsWith(':batch')) {
    batchBases.add(id.slice(0, -6));
  }
}

const byBaseId = new Map();
for (const m of rawModels) {
  if (!m || typeof m.id !== 'string') continue;
  let id = m.id.trim();
  if (!id || id.includes('~')) continue;

  const isBatchEntry = id.endsWith(':batch');
  const cleanNoBatch = isBatchEntry ? id.slice(0, -6) : id;
  const baseId = cleanNoBatch.endsWith(':online') ? cleanNoBatch.slice(0, -7) : cleanNoBatch;
  const slashIdx = baseId.indexOf('/');
  if (slashIdx === -1) continue;

  const rawProv = baseId.slice(0, slashIdx).toLowerCase();
  const modelName = baseId.slice(slashIdx + 1);
  if (!rawProv || !modelName) continue;

  if (!providersMap.has(rawProv)) {
    providersMap.set(rawProv, {
      provider_key: rawProv,
      discovered_model_count: 0,
      sample_models: [],
      _seen: new Set()
    });
  }
  const pEntry = providersMap.get(rawProv);
  if (!pEntry._seen.has(baseId)) {
    pEntry._seen.add(baseId);
    pEntry.discovered_model_count += 1;
    if (pEntry.sample_models.length < 5) {
      pEntry.sample_models.push(baseId);
    }
  }

  if (!allowedPrefixes.has(rawProv)) continue;

  const idLower = baseId.toLowerCase();
  if (blockedFragments.some(frag => idLower.includes(frag))) continue;

  const arch = m.architecture && typeof m.architecture === 'object' ? m.architecture : {};
  const inMods = Array.isArray(arch.input_modalities) ? arch.input_modalities.map(x => String(x).toLowerCase()) : ['text'];
  const outMods = Array.isArray(arch.output_modalities) ? arch.output_modalities.map(x => String(x).toLowerCase()) : ['text'];
  if (!inMods.includes('text') || !outMods.includes('text')) continue;
  if (outMods.includes('image') || outMods.includes('audio') || outMods.includes('video')) continue;

  const supportedParams = Array.isArray(m.supported_parameters)
    ? m.supported_parameters.map(p => String(p).toLowerCase())
    : [];
  const supportsTools = supportedParams.includes('tools');
  const supportsBatchApi = batchBases.has(baseId) || isBatchEntry;

  const existing = byBaseId.get(baseId);
  if (existing) {
    if (supportsBatchApi) {
      existing.supports_batch_api = true;
      existing.execution_strategy = 'batch_api';
    }
    if (supportsTools) {
      existing.supports_tools = true;
    }
    continue;
  }

  byBaseId.set(baseId, {
    id: baseId,
    canonical_id: baseId,
    provider: rawProv,
    model_name: modelName,
    display_name: m.name || baseId,
    eu_hosted: false,
    supports_web_search: true,
    supports_tools: supportsTools,
    supports_batch_api: supportsBatchApi,
    supports_prompt_caching: false,
    execution_strategy: supportsBatchApi ? 'batch_api' : 'regular',
    is_allowed: false,
    context_length: m.context_length || null,
    pricing: m.pricing || null,
    n8n_credential_id: 'tjmYBMIQa9Fo3kYL',
    n8n_credential_name: 'OpenRouter - Chatlytics - Chatlytics-dev-1'
  });
}

const providers = Array.from(providersMap.values())
  .map(p => ({
    provider_key: p.provider_key,
    discovered_model_count: p.discovered_model_count,
    sample_models: p.sample_models,
    is_relevant: allowedPrefixes.has(p.provider_key)
  }))
  .sort((a, b) => (b.discovered_model_count - a.discovered_model_count) || a.provider_key.localeCompare(b.provider_key));

const models = Array.from(byBaseId.values()).sort((a, b) => a.id.localeCompare(b.id));
return [{
  json: {
    status: 'ok',
    action: 'discover_models',
    source: 'openrouter_live_api',
    timestamp: new Date().toISOString(),
    count: models.length,
    provider_count: providers.length,
    provider_credentials: [
      {
        provider: 'openrouter',
        credential_id: 'tjmYBMIQa9Fo3kYL',
        credential_name: 'OpenRouter - Chatlytics - Chatlytics-dev-1',
        status: 'connected',
        models_discovered: models.length
      }
    ],
    providers,
    models
  }
}];

