const items = $input.all();
const normalizedItems = [];

const ALLOWED_OPENROUTER_PROVIDERS = new Set([
  'openai', 'google', 'anthropic', 'mistralai', 'x-ai',
  'deepseek', 'qwen', 'xiaomi', 'z-ai', 'zhipu',
  'meta-llama', 'meta', 'nvidia', 'azure', 'microsoft', 'perplexity',
  'moonshotai', 'moonshot', 'minimax'
]);

const DEFAULT_BATCH_PROVIDERS = new Set(['openai', 'google', 'anthropic', 'mistralai', 'z-ai']);

function sanitizeMarketRegion(raw) {
  if (raw === null || raw === undefined) return null;
  const s = String(raw).trim();
  if (!s) return null;
  const low = s.toLowerCase();
  if (low === 'auto' || low === 'default' || low === 'none' || low === 'null') return null;
  return s.slice(0, 64);
}

function resolveModelSpec(rawToken, searchEnabled, isTestRun, triggerSource, supportsBatchOverride, supportsToolsOverride) {
  const clean = String(rawToken || '').trim();
  if (!clean) return null;
  const lower = clean.toLowerCase();

  let canonicalId = '';
  let provider = '';
  let model = '';

  if (clean.includes('/')) {
    const slashIdx = clean.indexOf('/');
    const rawProv = clean.slice(0, slashIdx).trim().toLowerCase();
    let modelTrim = clean.slice(slashIdx + 1).trim();
    if (modelTrim.endsWith(':batch')) {
      modelTrim = modelTrim.slice(0, -6);
    }

    if (rawProv === 'models' && modelTrim.toLowerCase().startsWith('gemini')) {
      provider = 'google';
      model = modelTrim;
    } else if (rawProv === 'gemini' || rawProv === 'google') {
      provider = 'google';
      const stripped = modelTrim.toLowerCase().startsWith('models/') ? modelTrim.slice(7) : modelTrim;
      model = stripped || 'gemini-3.5-flash';
    } else if (rawProv === 'openai') {
      provider = 'openai';
      model = modelTrim || 'gpt-6-luna';
    } else if (rawProv === 'mistral' || rawProv === 'mistralai' || rawProv === 'eu-mistral') {
      const mLower = modelTrim.toLowerCase();
      if (mLower === 'zai-glm-5-3') {
        provider = 'z-ai';
        model = 'glm-5.3';
      } else if (mLower === 'zai-glm-5-3-flash') {
        provider = 'z-ai';
        model = 'glm-5.3-flash';
      } else if (mLower === 'mistral-medium-latest' || !mLower) {
        provider = 'mistralai';
        model = 'mistral-medium-3-5';
      } else if (mLower === 'mistral-large-latest') {
        provider = 'mistralai';
        model = 'mistral-large-4-0';
      } else {
        provider = 'mistralai';
        model = modelTrim;
      }
    } else if (rawProv === 'glm' || rawProv === 'zai' || rawProv === 'z.ai' || rawProv === 'z-ai') {
      provider = 'z-ai';
      model = modelTrim || 'glm-5.3';
    } else if (rawProv === 'anthropic') {
      provider = 'anthropic';
      model = modelTrim || 'claude-sonnet-5.5';
    } else if (ALLOWED_OPENROUTER_PROVIDERS.has(rawProv)) {
      provider = rawProv === 'zhipu' ? 'z-ai' : rawProv;
      model = modelTrim;
    } else {
      provider = rawProv;
      model = modelTrim;
    }
    canonicalId = model ? (provider + '/' + model) : provider;
  } else {
    if (lower === 'openai') {
      provider = 'openai';
      model = 'gpt-6-luna';
    } else if (lower.startsWith('gpt-') || /^o[134](-|$)/.test(lower)) {
      provider = 'openai';
      model = clean;
    } else if (lower === 'gemini' || lower === 'google') {
      provider = 'google';
      model = 'gemini-3.5-flash';
    } else if (lower.startsWith('gemini-')) {
      provider = 'google';
      model = clean;
    } else if (lower === 'mistral' || lower === 'mistralai' || lower === 'mistral-medium-latest') {
      provider = 'mistralai';
      model = 'mistral-medium-3-5';
    } else if (lower === 'mistral-large-latest') {
      provider = 'mistralai';
      model = 'mistral-large-4-0';
    } else if (
      lower.startsWith('mistral-')
      || lower.startsWith('pixtral-')
      || lower.startsWith('codestral-')
      || lower.startsWith('ministral-')
    ) {
      provider = 'mistralai';
      model = clean;
    } else if (lower === 'glm' || lower === 'glm-5-3' || lower === 'zai-glm-5-3' || lower === 'glm-5.3') {
      provider = 'z-ai';
      model = 'glm-5.3';
    } else if (lower === 'glm-5-3-flash' || lower === 'zai-glm-5-3-flash' || lower === 'glm-5.3-flash') {
      provider = 'z-ai';
      model = 'glm-5.3-flash';
    } else if (lower.startsWith('zai-glm') || lower.startsWith('glm-')) {
      provider = 'z-ai';
      model = clean.replace(/^zai-/i, '');
    } else if (lower === 'anthropic') {
      provider = 'anthropic';
      model = 'claude-sonnet-5.5';
    } else if (lower.startsWith('claude-')) {
      provider = 'anthropic';
      model = clean;
    } else if (lower.startsWith('sonar') || lower === 'perplexity') {
      provider = 'perplexity';
      model = lower === 'perplexity' ? 'sonar-pro' : clean;
    } else {
      provider = lower;
      model = clean;
    }
    canonicalId = model ? (provider + '/' + model) : provider;
  }

  const supportsBatchApi = typeof supportsBatchOverride === 'boolean'
    ? supportsBatchOverride
    : DEFAULT_BATCH_PROVIDERS.has(provider);

  const supportsTools = typeof supportsToolsOverride === 'boolean'
    ? supportsToolsOverride
    : (provider !== 'perplexity');

  const canBatch = !searchEnabled && !isTestRun && triggerSource !== 'chat' && supportsBatchApi;
  const executionStrategy = canBatch ? 'batch_api' : 'regular';

  return {
    id: canonicalId,
    provider,
    model,
    eu_hosted: false,
    supports_prompt_caching: false,
    supports_batch_api: supportsBatchApi,
    supports_tools: supportsTools,
    execution_strategy: executionStrategy
  };
}

function parseShorthand(text) {
  const result = {
    prompt: '',
    brand_name: '',
    brand_domains: [],
    competitors: [],
    target_llms: ['openai/gpt-6-luna', 'google/gemini-3.5-flash'],
    search_enabled: true,
    market_region: null
  };
  if (!text || typeof text !== 'string') return result;

  const lines = text.split(/[\n|]/);
  for (const line of lines) {
    const colonIdx = line.indexOf(':');
    if (colonIdx === -1) {
      if (!result.prompt && line.trim()) result.prompt = line.trim();
      continue;
    }
    const key = line.slice(0, colonIdx).trim().toUpperCase();
    const val = line.slice(colonIdx + 1).trim();
    if (key === 'PROMPT') {
      result.prompt = val;
    } else if (key === 'BRAND') {
      result.brand_name = val;
    } else if (key === 'DOMAINS') {
      result.brand_domains = val.split(',').map(d => d.trim().toLowerCase()).filter(Boolean);
    } else if (key === 'COMPETITORS') {
      result.competitors = val.split(',').map(c => {
        const match = c.match(/^(.*?)(?:\s*\((.*?)\))?$/);
        return {
          name: match ? match[1].trim() : c.trim(),
          domain: match && match[2] ? match[2].trim().toLowerCase() : ''
        };
      }).filter(c => c.name);
    } else if (key === 'LLMS') {
      const parsedLlms = val.split(',').map(l => l.trim()).filter(Boolean);
      if (parsedLlms.length > 0) result.target_llms = parsedLlms;
    } else if (key === 'SEARCH') {
      result.search_enabled = val.toLowerCase() === 'true' || val === '1';
    } else if (key === 'REGION' || key === 'MARKET' || key === 'MARKET_REGION') {
      result.market_region = sanitizeMarketRegion(val);
    }
  }
  return result;
}

function expandTargetLLMs(input, triggerSource, inputIdx, defaultApiBaseUrl) {
  if (!input || typeof input !== 'object') return [];
  const rawPrompts = Array.isArray(input.prompts)
    ? input.prompts.map(p => String(p || '').trim()).filter(Boolean)
    : [];
  const primaryPrompt = String(input.prompt || '').trim();
  if (triggerSource === 'schedule_queue' && rawPrompts.length === 0 && !primaryPrompt) {
    return [];
  }
  const promptList = rawPrompts.length > 0 ? rawPrompts : [primaryPrompt];

  const brandName = String(input.brand_name || '').trim();
  const brandDomains = Array.isArray(input.brand_domains) ? input.brand_domains.filter(Boolean) : [];
  const competitors = (Array.isArray(input.competitors) ? input.competitors : []).map(c => {
    if (typeof c === 'string') return { name: c.trim(), domain: '', domains: [] };
    if (c && typeof c === 'object') {
      const domains = Array.isArray(c.domains)
        ? c.domains.map(d => String(d || '').trim().toLowerCase()).filter(Boolean)
        : [];
      const singleDom = String(c.domain || c.competitor_domain || '').trim().toLowerCase();
      if (singleDom && !domains.includes(singleDom)) domains.unshift(singleDom);
      return {
        name: String(c.name || c.competitor_name || '').trim(),
        domain: domains[0] || '',
        domains
      };
    }
    return null;
  }).filter(c => c && c.name);

  let searchEnabled = true;
  if (input.search_enabled !== undefined) {
    searchEnabled = typeof input.search_enabled === 'string'
      ? (input.search_enabled.toLowerCase() === 'true' || input.search_enabled === '1')
      : Boolean(input.search_enabled);
  }

  const isTestRun = Boolean(input.is_test_run);
  const marketRegion = sanitizeMarketRegion(input.market_region ?? input.region ?? null);
  const batchRequestsList = Array.isArray(input.batch_requests) ? input.batch_requests : [];

  let rawTargetLLMs = input.target_llms;
  if (typeof rawTargetLLMs === 'string') {
    rawTargetLLMs = rawTargetLLMs.split(',').map(s => s.trim()).filter(Boolean);
  }
  if (!Array.isArray(rawTargetLLMs) || rawTargetLLMs.length === 0) {
    rawTargetLLMs = ['openai/gpt-6-luna', 'google/gemini-3.5-flash'];
  }

  const seenSpecs = new Set();
  const specs = [];
  for (const token of rawTargetLLMs) {
    if (token === null || token === undefined) continue;
    const spec = resolveModelSpec(
      String(token),
      searchEnabled,
      isTestRun,
      triggerSource,
      typeof input.supports_batch_api === 'boolean' ? input.supports_batch_api : undefined,
      typeof input.supports_tools === 'boolean' ? input.supports_tools : undefined
    );
    if (spec && spec.id && !seenSpecs.has(spec.id)) {
      seenSpecs.add(spec.id);
      specs.push(spec);
    }
  }
  if (specs.length === 0) {
    specs.push(
      resolveModelSpec('openai/gpt-6-luna', searchEnabled, isTestRun, triggerSource),
      resolveModelSpec('google/gemini-3.5-flash', searchEnabled, isTestRun, triggerSource)
    );
  }

  const responseMode = input.response_mode || ((input.is_async === true || input.is_async === 'true') ? 'async' : (triggerSource === 'chat' ? 'sync' : (triggerSource === 'webhook' ? 'sync' : 'async')));
  const configId = input.config_id || null;
  const userId = input.user_id || null;
  const rawBaseUrl = String(input.api_base_url || defaultApiBaseUrl || 'https://chatlytics.de').trim().replace(/\/+$/, '');
  const apiBaseUrl = rawBaseUrl || 'https://chatlytics.de';
  const runId = input.run_id || ('run_' + Date.now() + '_' + Math.floor(Math.random() * 0x100000000).toString(16).padStart(8, '0'));
  const createdAt = new Date().toISOString();

  const expanded = [];
  for (let pIdx = 0; pIdx < promptList.length; pIdx++) {
    const promptText = promptList[pIdx];
    for (const spec of specs) {
      const matchedBatchItem = batchRequestsList.find(br =>
        br && br.prompt === promptText && (
          br.model_key === spec.id
          || br.target_llm === spec.id
          || (br.provider === spec.provider && br.model === spec.model)
        )
      );
      const itemSupportsBatch = typeof matchedBatchItem?.supports_batch_api === 'boolean'
        ? matchedBatchItem.supports_batch_api
        : spec.supports_batch_api;
      const itemSupportsTools = typeof matchedBatchItem?.supports_tools === 'boolean'
        ? matchedBatchItem.supports_tools
        : spec.supports_tools;

      const canItemBatch = !searchEnabled && !isTestRun && triggerSource !== 'chat' && itemSupportsBatch;
      const resolvedStrategy = canItemBatch ? 'batch_api' : 'regular';

      const resolvedCustomId = (matchedBatchItem && matchedBatchItem.custom_id)
        || (promptList.length === 1 && specs.length === 1 && input.custom_id ? String(input.custom_id) : null)
        || ('cl_u' + (userId || 0) + '_c' + (configId || 0) + '_p' + pIdx + '_' + spec.provider + '_' + Date.now() + '_' + Math.floor(Math.random() * 0xffff).toString(16));

      expanded.push({
        json: {
          run_id: runId,
          custom_id: resolvedCustomId,
          batch_id: input.batch_id || null,
          execution_strategy: resolvedStrategy,
          supports_prompt_caching: false,
          supports_batch_api: itemSupportsBatch,
          supports_tools: itemSupportsTools,
          prompt_cache_key: null,
          prompt_cache_retention: null,
          is_test_run: isTestRun,
          api_base_url: apiBaseUrl,
          prompt_index: pIdx,
          config_id: configId,
          user_id: userId,
          trigger_source: triggerSource,
          response_mode: responseMode,
          prompt: promptText,
          llm_prompt: promptText,
          market_region: matchedBatchItem?.market_region ?? marketRegion,
          brand_name: brandName,
          brand_domains: brandDomains,
          competitors,
