const items = $input.all();
if (!items.length) return [];

const groups = new Map();
for (let i = 0; i < items.length; i++) {
  const d = items[i].json || {};
  const modelSlug = (d.model_key && String(d.model_key).includes('/'))
    ? String(d.model_key).trim()
    : ((d.provider || 'openai') + '/' + (d.model || 'gpt-6-luna'));
  const apiBase = String(d.api_base_url || 'https://chatlytics.de').trim().replace(/\/+$/, '') || 'https://chatlytics.de';
  const groupKey = apiBase + '::' + modelSlug;
  if (!groups.has(groupKey)) {
    groups.set(groupKey, { apiBase, modelSlug, rows: [] });
  }
  groups.get(groupKey).rows.push(d);
}

const MAX_BATCH_SIZE = 1000;
const batches = [];

for (const group of groups.values()) {
  for (let start = 0; start < group.rows.length; start += MAX_BATCH_SIZE) {
    const chunk = group.rows.slice(start, start + MAX_BATCH_SIZE);
    const requests = chunk.map(row => ({
      custom_id: row.custom_id,
      body: {
        messages: [
          {
            role: 'user',
            content: row.llm_prompt || row.prompt || ''
          }
        ],
        temperature: 0.2
      }
    }));

    batches.push({
      json: {
        openrouter_model: group.modelSlug,
        api_base_url: group.apiBase,
        custom_ids: chunk.map(r => r.custom_id).filter(Boolean),
        request_count: requests.length,
        request_body: {
          endpoint: '/v1/chat/completions',
          model: group.modelSlug,
          requests
        },
        batch_items_meta: chunk
      }
    });
  }
}

return batches;

const items = $input.all();
const output = [];

for (let i = 0; i < items.length; i++) {
  const resp = items[i].json || {};
  let upstream = {};
  try {
    if (typeof $ === 'function') {
      upstream = $('Prepare OpenRouter Batches').itemMatching(i)?.json || $('Prepare OpenRouter Batches').all()[i]?.json || {};
    }
  } catch (_) {}

  const apiBaseUrl = upstream.api_base_url || 'https://chatlytics.de';
  const customIds = Array.isArray(upstream.custom_ids) ? upstream.custom_ids : [];
  const hasHttpError = resp.error || (typeof resp.statusCode === 'number' && resp.statusCode >= 400);
  const batchId = resp.id || resp.batch_id || null;

  if (!hasHttpError && batchId) {
    output.push({
      json: {
        _submit_ok: true,
        api_base_url: apiBaseUrl,
        provider_batch_id: String(batchId),
        batch_status: resp.status || 'validating',
        custom_ids: customIds,
        target_llm: upstream.openrouter_model || null
      }
    });
  } else {
    const errMsg = (resp.error && (resp.error.message || JSON.stringify(resp.error)))
      || resp.message
      || ('OpenRouter Batch submission failed (HTTP ' + (resp.statusCode || 500) + ')');
    output.push({
      json: {
        _submit_ok: false,
        api_base_url: apiBaseUrl,
        provider_batch_id: null,
        custom_ids: customIds,
        error_message: String(errMsg)
      }
    });
  }
}

return output;

const items = $input.all();
const results = [];

function extractDomainFromUrl(urlOrDomain) {
  if (!urlOrDomain || typeof urlOrDomain !== 'string') return '';
  let clean = urlOrDomain.trim();
  try {
    clean = decodeURIComponent(clean);
  } catch (_) {
    clean = clean.replace(/%2f/gi, '/').replace(/%3a/gi, ':').replace(/%40/gi, '@');
  }
  clean = clean.toLowerCase().replace(/^https?:\/\//i, '');
  const atIdx = clean.indexOf('@');
  const firstSlash = clean.indexOf('/');
  if (atIdx !== -1 && (firstSlash === -1 || atIdx < firstSlash)) {
    clean = clean.slice(atIdx + 1);
  }
  clean = clean.replace(/^www\./i, '');
  for (const sep of ['/', ':', '?', '#']) {
    const idx = clean.indexOf(sep);
    if (idx !== -1) clean = clean.slice(0, idx);
  }
  return clean.trim();
}

function matchesDomain(candidateDomain, registeredDomains) {
  if (!candidateDomain || !registeredDomains) return false;
  const regList = Array.isArray(registeredDomains) ? registeredDomains : [registeredDomains];
  const cleanCand = extractDomainFromUrl(String(candidateDomain));
  if (!cleanCand) return false;
  return regList.some(reg => {
    const cleanReg = extractDomainFromUrl(String(reg));
    return cleanReg && (cleanCand === cleanReg || cleanCand.endsWith('.' + cleanReg));
  });
}

function extractErrorInfo(data) {
  if (!data || typeof data !== 'object') return null;

  if (data.error !== null && data.error !== undefined) {
    if (typeof data.error === 'string' && data.error.trim()) {
      return data.error.trim();
    }
    if (typeof data.error === 'object') {
      const msg = data.error.message || data.error.msg || data.error.description;
      if (msg) return String(msg).trim();
      return JSON.stringify(data.error);
    }
  }

  if (data.object === 'error') {
    return String(data.message || data.detail || 'OpenRouter returned error object').trim();
  }

  if (typeof data.errorMessage === 'string' && data.errorMessage.trim()) {
    return data.errorMessage.trim();
  }

  if (data.detail && !data.choices && !data.candidates && !data.output && !data.content) {
    if (Array.isArray(data.detail)) {
      return data.detail.map(d => (d && d.msg ? d.msg : JSON.stringify(d))).join('; ');
    }
    return String(data.detail).trim();
  }

  if (typeof data.statusCode === 'number' && data.statusCode >= 400) {
    return String(data.message || data.statusMessage || ('HTTP ' + data.statusCode));
  }

  if (data.status === 'failed' || data.status === 'error') {
    return String(data.message || data.incomplete_details?.reason || 'LLM provider returned failed status');
  }

  if (
    typeof data.message === 'string'
    && data.message.trim()
    && !data.choices
    && !data.candidates
    && !data.output
    && !data.content
    && !data.raw_response_text
    && !data.raw_response
    && !data.text
    && !data.prompt
  ) {
    return data.message.trim();
  }

  return null;
}

function joinPartsText(parts) {
  if (!Array.isArray(parts)) return '';
  const nonThought = parts
    .filter(p => p && !p.thought && typeof p.text === 'string')
    .map(p => p.text);
  if (nonThought.length > 0) return nonThought.join('');
  return parts
    .filter(p => p && typeof p.text === 'string')
    .map(p => p.text)
    .join('');
}

function extractInputTokens(data) {
  if (!data || typeof data !== 'object') return 0;
  if (typeof data.input_tokens === 'number') return Math.max(0, Math.floor(data.input_tokens));
  if (typeof data.prompt_tokens === 'number') return Math.max(0, Math.floor(data.prompt_tokens));
  const u = data.usage || {};
  if (typeof u.prompt_tokens === 'number') return Math.max(0, Math.floor(u.prompt_tokens));
  if (typeof u.input_tokens === 'number') return Math.max(0, Math.floor(u.input_tokens));
  return 0;
}

function extractOutputTokens(data) {
  if (!data || typeof data !== 'object') return 0;
  if (typeof data.output_tokens === 'number') return Math.max(0, Math.floor(data.output_tokens));
  if (typeof data.completion_tokens === 'number') return Math.max(0, Math.floor(data.completion_tokens));
  const u = data.usage || {};
  if (typeof u.completion_tokens === 'number') return Math.max(0, Math.floor(u.completion_tokens));
  if (typeof u.output_tokens === 'number') return Math.max(0, Math.floor(u.output_tokens));
  return 0;
}

function extractResponseText(data) {
  if (!data || typeof data !== 'object') return '';

  // 1. OpenRouter Unified Chat Completions format
  if (data.choices && Array.isArray(data.choices) && data.choices[0]?.message?.content !== undefined) {
    const content = data.choices[0].message.content;
    if (typeof content === 'string') return content;
    if (Array.isArray(content)) {
      return content
        .map(part => {
          if (typeof part === 'string') return part;
          if (part && typeof part.text === 'string' && (!part.type || part.type === 'text' || part.type === 'output_text')) {
            return part.text;
          }
          return '';
        })
        .join('');
    }
  }

  // 2. Fallback compatibility formats
  if (Array.isArray(data.output)) {
    const chunks = [];
    for (const block of data.output) {
      if (!block) continue;
      if (typeof block === 'string') chunks.push(block);
      else if (Array.isArray(block.content)) {
        for (const part of block.content) {
          if (typeof part === 'string') chunks.push(part);
          else if (part && typeof part.text === 'string') chunks.push(part.text);
        }
      } else if (typeof block.text === 'string') chunks.push(block.text);
    }
    if (chunks.length > 0) return chunks.join('\n').trim();
  }
  if (typeof data.output_text === 'string' && data.output_text) return data.output_text;
  if (typeof data.output === 'string' && data.output) return data.output;
  if (data.candidates && Array.isArray(data.candidates) && data.candidates[0]?.content?.parts) {
    return joinPartsText(data.candidates[0].content.parts);
  }
  if (data.content && Array.isArray(data.content)) {
    const texts = data.content.filter(c => c && typeof c.text === 'string').map(c => c.text);
    if (texts.length > 0) return texts.join('');
  }
  if (data.raw_response_text !== undefined && data.raw_response_text !== null) return String(data.raw_response_text);
  if (data.raw_response !== undefined && data.raw_response !== null) return String(data.raw_response);
  if (data.text !== undefined && data.text !== null) return String(data.text);

  return '';
}

function addCitation(citations, seenUrls, url, title, sourceType) {
  const cleanUrl = String(url || '').trim();
  if (!cleanUrl || seenUrls.has(cleanUrl)) return;
  seenUrls.add(cleanUrl);
  const domain = extractDomainFromUrl(cleanUrl);
  const cleanTitle = title ? String(title).trim() : 'Untitled';
  citations.push({
    citation_url: cleanUrl,
    citation_domain: domain,
    domain,
    citation_title: cleanTitle || 'Untitled',
    title: cleanTitle || 'Untitled',
    source_type: sourceType
  });
}

function extractCitations(data, rawText, brandDomains, competitorList) {
  const citations = [];
  const seenUrls = new Set();
  const safeCompList = (Array.isArray(competitorList) ? competitorList : []).filter(Boolean);

  // 1. Gemini Grounding Metadata Chunks (native or passthrough)
  const geminiChunks = data.candidates?.[0]?.groundingMetadata?.groundingChunks
    || data.groundingMetadata?.groundingChunks;
  if (Array.isArray(geminiChunks)) {
    for (const chunk of geminiChunks) {
      if (chunk && chunk.web && chunk.web.uri) {
        addCitation(citations, seenUrls, chunk.web.uri, chunk.web.title, 'grounding_metadata');
      }
    }
  }

  // 2. OpenRouter / OpenAI Annotations (web_search tool & web plugin)
  const collectAnnotations = (annotations) => {
    if (!Array.isArray(annotations)) return;
    for (const ann of annotations) {
      if (!ann || typeof ann !== 'object') continue;
      if (ann.type === 'url_citation' || ann.url_citation || ann.url) {
        const citUrl = ann.url || ann.url_citation?.url;
        const citTitle = ann.title || ann.url_citation?.title || 'Untitled';
        if (citUrl) addCitation(citations, seenUrls, citUrl, citTitle, 'openrouter_web_search');
      }
    }
  };
  if (Array.isArray(data.output)) {
    for (const block of data.output) {
      if (block && Array.isArray(block.content)) {
        for (const part of block.content) {
          if (part && Array.isArray(part.annotations)) collectAnnotations(part.annotations);
        }
      }
    }
  }
  collectAnnotations(data.choices?.[0]?.message?.annotations);
  collectAnnotations(data.annotations);
  if (Array.isArray(data.citations)) {
    for (const c of data.citations) {
      if (typeof c === 'string') addCitation(citations, seenUrls, c, 'Untitled', 'perplexity_citation');
      else if (c && (c.url || c.citation_url)) addCitation(citations, seenUrls, c.url || c.citation_url, c.title || c.citation_title || 'Untitled', 'provider_citation');
    }
  }

  // 2. Markdown Links in Text
  if (rawText && typeof rawText === 'string') {
    const mdRegex = /\[(.*?)\]\((https?:\/\/[^\s)]+)\)/g;
    let match;
    while ((match = mdRegex.exec(rawText)) !== null) {
      addCitation(citations, seenUrls, match[2], match[1], 'markdown_link');
    }

    // 3. Bare URLs
    const textWithoutMd = rawText.replace(/\[(.*?)\]\(https?:\/\/[^\s)]+\)/g, ' ');
    const bareRegex = /https?:\/\/(?:[a-zA-Z0-9_.-]+(?::[a-zA-Z0-9_.-]+)?@)?[a-zA-Z0-9.-]+(?::\d+)?(?:\/[^\s)]*)?/g;
    const bareMatches = textWithoutMd.match(bareRegex) || [];
    for (const rawUrl of bareMatches) {
      const cleanUrl = rawUrl.replace(/[.,;:!\])]+$/, '');
      addCitation(citations, seenUrls, cleanUrl, 'Untitled', 'bare_url');
    }
  }

  return citations.map((c, idx) => {
    const isBrand = matchesDomain(c.citation_domain, brandDomains);
    const isComp = safeCompList.some(comp => {
      if (typeof comp === 'string') return matchesDomain(c.citation_domain, comp);
      if (!comp || typeof comp !== 'object') return false;
      const doms = [];
      if (comp.domain) doms.push(comp.domain);
      if (comp.competitor_domain) doms.push(comp.competitor_domain);
      if (Array.isArray(comp.domains)) doms.push(...comp.domains);
      return doms.length > 0 && matchesDomain(c.citation_domain, doms);
    });
    return {
      citation_index: idx + 1,
      citation_url: c.citation_url,
      citation_domain: c.citation_domain,
      domain: c.citation_domain,
      citation_title: c.citation_title,
      title: c.citation_title,
      is_brand_domain: isBrand,
      is_competitor_domain: isComp,
      source_type: c.source_type
    };
  });
}

function inferProviderFromPayload(data) {
  if (!data || typeof data !== 'object') return null;
  if (typeof data.model === 'string' && data.model.includes('/')) {
    return data.model.slice(0, data.model.indexOf('/')).toLowerCase();
  }
  if (Array.isArray(data.candidates)) return 'google';
  if (Array.isArray(data.output) || data.object === 'response') return 'openai';
  if (data.type === 'message' || Array.isArray(data.content)) return 'anthropic';
  return null;
}

function resolveUpstreamMeta(i, rawPayload, totalBranchItems) {
  if (rawPayload && rawPayload.raw_payload_source === 'openrouter_batch') {
    return {};
  }
  if (typeof $ !== 'function') return {};
  for (const nodeName of ['Execution Strategy Router', 'Apply Localized Market Extension', 'Universal Normalizer']) {
    try {
      const nodeRef = $(nodeName);
      if (nodeRef && typeof nodeRef.itemMatching === 'function') {
        const matched = nodeRef.itemMatching(i);
        if (matched && matched.json && typeof matched.json === 'object' && Object.keys(matched.json).length > 0) {
          return matched.json;
        }
      }
    } catch (_) {}
  }

  for (const nodeName of ['Apply Localized Market Extension', 'Universal Normalizer', 'Execution Strategy Router']) {
    try {
      const nodeRef = $(nodeName);
      const allMeta = nodeRef && typeof nodeRef.all === 'function' ? nodeRef.all() : [];
      if (!Array.isArray(allMeta) || allMeta.length === 0) continue;
      if (allMeta.length === 1 && allMeta[0]?.json && Object.keys(allMeta[0].json).length > 0) {
        return allMeta[0].json;
      }
      if (allMeta.length === totalBranchItems && allMeta[i]?.json && Object.keys(allMeta[i].json).length > 0) {
        return allMeta[i].json;
      }
      const inferred = inferProviderFromPayload(rawPayload);
      if (inferred) {
        const providerMatches = allMeta.filter(m => {
          const p = String(m?.json?.provider || m?.json?.selected_provider || '').toLowerCase();
          if (!p) return false;
          if (p === inferred) return true;
          if (inferred === 'google' && p === 'gemini') return true;
          return false;
        });
        if (providerMatches.length === totalBranchItems && providerMatches[i]?.json) {
          return providerMatches[i].json;
        }
        if (providerMatches.length === 1 && providerMatches[0]?.json) {
          return providerMatches[0].json;
        }
      }
    } catch (_) {}
  }

  return {};
}

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const rawPayload = (item && item.json && typeof item.json === 'object') ? item.json : {};
  const meta = resolveUpstreamMeta(i, rawPayload, items.length);

  const resolvedModelSlug = String(meta.model_key || meta.target_llm || rawPayload.target_llm || rawPayload.model || 'openai/gpt-6-luna');
  let resolvedProvider = meta.provider || meta.selected_provider || rawPayload.provider || rawPayload.selected_provider || '';
  let resolvedModel = meta.model || '';
  if (resolvedModelSlug.includes('/')) {
    const idx = resolvedModelSlug.indexOf('/');
    if (!resolvedProvider) resolvedProvider = resolvedModelSlug.slice(0, idx);
    if (!resolvedModel) resolvedModel = resolvedModelSlug.slice(idx + 1);
  }
  resolvedProvider = resolvedProvider || 'openai';
  resolvedModel = resolvedModel || 'gpt-6-luna';

  const errorMessage = extractErrorInfo(rawPayload);
  let rawText = extractResponseText(rawPayload);
  let status = 'completed';
  let isError = false;

  if (errorMessage) {
    isError = true;
    status = 'failed';
    rawText = 'ERROR: ' + errorMessage;
  }

  const brandDomains = meta.brand_domains || rawPayload.brand_domains || [];
  const competitors = meta.competitors || rawPayload.competitors || [];
  const extractedCitations = isError
    ? []
    : extractCitations(rawPayload, rawText, brandDomains, competitors);

  const inputTokens = extractInputTokens(rawPayload);
  const outputTokens = extractOutputTokens(rawPayload);

  results.push({
    json: {
      ...meta,
      ...rawPayload,
      run_id: meta.run_id || rawPayload.run_id,
      custom_id: meta.custom_id || rawPayload.custom_id || null,
      batch_id: meta.batch_id || rawPayload.batch_id || null,
      execution_strategy: meta.execution_strategy || rawPayload.execution_strategy || 'regular',
      prompt_cache_key: null,
      input_tokens: inputTokens,
      output_tokens: outputTokens,
      cached_tokens: 0,
      is_test_run: Boolean(meta.is_test_run || rawPayload.is_test_run),
      api_base_url: meta.api_base_url || rawPayload.api_base_url || 'https://chatlytics.de',
      config_id: meta.config_id ?? rawPayload.config_id,
      user_id: meta.user_id ?? rawPayload.user_id,
      prompt: meta.prompt !== undefined ? meta.prompt : rawPayload.prompt,
      llm_prompt: meta.llm_prompt || meta.prompt || rawPayload.llm_prompt || rawPayload.prompt,
      market_region: meta.market_region !== undefined ? meta.market_region : (rawPayload.market_region ?? null),
      brand_name: meta.brand_name !== undefined ? meta.brand_name : rawPayload.brand_name,
      brand_domains: brandDomains,
      provider: resolvedProvider,
      selected_provider: resolvedProvider,
      model: resolvedModel,
      model_key: resolvedModelSlug,
      model_name: resolvedModel,
      eu_hosted: false,
      is_eu_hosted: false,
      search_enabled: meta.search_enabled !== undefined ? Boolean(meta.search_enabled) : Boolean(rawPayload.search_enabled),
      status,
      is_error: isError,
      error_message: errorMessage || null,
      raw_response: rawText,
      raw_response_text: rawText,
      text: rawText,
      citations: extractedCitations,
      competitors: (Array.isArray(competitors) ? competitors : []).filter(Boolean).map(c => {
        if (typeof c === 'string') return { name: c, domain: '', domains: [] };
        const doms = Array.isArray(c.domains) ? c.domains.filter(Boolean) : [];
        const dom = c.domain || c.competitor_domain || doms[0] || '';
        if (dom && !doms.includes(dom)) doms.unshift(dom);
        return { ...c, name: c.name || c.competitor_name || '', domain: dom, domains: doms };
      })
    }
  });
}

return results;

/**
 * Chatlytics.de — Deterministic Unicode Metric & Classification Engine
